import{useEffect,useMemo,useState}from'react';import{ArrowLeft,ArrowRight,BadgePercent,BrainCircuit,Check,Clock3,IndianRupee,Lightbulb,PackageCheck,ShieldCheck,ShoppingBag,Sparkles,Target,TriangleAlert}from'lucide-react';import api,{message}from'./api';import{PageTitle}from'./Features';
const categories=['ELECTRONICS','CLOTHING','FOOD','BEAUTY','ENTERTAINMENT','HOME','TRAVEL','GAMING','ACCESSORIES','OTHER'];const moods=[['NORMAL','Calm'],['HAPPY','Happy'],['EXCITED','Excited'],['BORED','Bored'],['STRESSED','Stressed'],['SAD','Sad'],['FRUSTRATED','Frustrated']];const pretty=v=>(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v||0);
const blank={productName:'',category:'ELECTRONICS',price:'',description:'',sourceOfInterest:'SOCIAL_MEDIA',discountAvailable:false,discountPercentage:0,genuinelyNeeded:null,previouslyPlanned:null,considerationPeriod:'Today',ownsSimilar:null,withinBudget:true,advertisementTriggered:null,discountTriggered:null,offerUrgency:null,emotionalState:'NORMAL',canWait:null,frequentlyUsed:null,cheaperAlternative:null};
const questions=[['genuinelyNeeded','Do you genuinely need it?','Imagine it was full price and unavailable today. Would you still need it?'],['previouslyPlanned','Was this purchase planned?','A list, calendar note, or prior budget counts as planning.'],['ownsSimilar','Do you own something similar?','Think about products that solve the same problem.'],['withinBudget','Does it fit your available budget?','Only count money left after essentials and savings.'],['advertisementTriggered','Did an ad introduce the urge?','Social posts, creator links, emails, and retargeting count.'],['discountTriggered','Is the discount driving the decision?','Would you want it without the sale badge?'],['offerUrgency','Does the offer feel urgent?','Limited stock and countdown timers are designed to speed decisions.'],['canWait','Could you comfortably wait?','A real need usually survives a short pause.'],['frequentlyUsed','Will you use it often?','Choose yes only if you can name a regular use.'],['cheaperAlternative','Is there a cheaper alternative?','Borrowing, repairing, buying used, or another brand all count.']];
function Choice({value,onChange,yes='Yes',no='No'}){return <div className="binary-choice"><button type="button" className={value===true?'active yes':''} onClick={()=>onChange(true)}><Check/>{yes}</button><button type="button" className={value===false?'active no':''} onClick={()=>onChange(false)}>× {no}</button></div>}
export default function EvaluatePage(){const[step,setStep]=useState(0),[form,setForm]=useState(blank),[budget,setBudget]=useState(),[result,setResult]=useState(),[busy,setBusy]=useState(false),[error,setError]=useState(''),[saved,setSaved]=useState(false);const set=(key,value)=>setForm(f=>({...f,[key]:value}));useEffect(()=>{api.get('/budget').then(r=>setBudget(r.data)).catch(()=>{})},[]);useEffect(()=>{if(form.price&&budget?.remainingBudget!==undefined)set('withinBudget',Number(form.price)<=Number(budget.remainingBudget))},[form.price,budget]);const answered=questions.filter(([k])=>form[k]!==null).length;const priceAfterDiscount=useMemo(()=>Number(form.price||0)*(1-Number(form.discountPercentage||0)/100),[form.price,form.discountPercentage]);function next(){setError('');if(step===0&&(!form.productName.trim()||Number(form.price)<=0)){setError('Add a product name and a valid price to continue.');return}setStep(s=>Math.min(2,s+1))}async function evaluate(){if(answered<questions.length){setError(`Answer all reflection questions first (${answered}/${questions.length} complete).`);return}setBusy(true);setError('');try{const{data}=await api.post('/evaluations',{...form,price:Number(form.price),discountPercentage:Number(form.discountPercentage||0)});setResult(data)}catch(e){setError(message(e))}finally{setBusy(false)}}async function decision(value){const{data}=await api.put(`/evaluations/${result.id}/decision`,{decision:value});setResult(data)}async function wishlist(){const hours=result.riskLevel==='VERY_HIGH'?168:result.riskLevel==='HIGH'?48:24;await api.post('/wishlist',{productName:result.productName,category:result.category,price:result.price,status:'WAITING',waitingUntil:new Date(Date.now()+hours*3600000).toISOString().slice(0,19)});await decision('WAITING');setSaved(true)}function reset(){setForm(blank);setStep(0);setResult();setSaved(false)}
 if(result)return <><PageTitle eyebrow="YOUR MINDFUL VERDICT" title="A clearer decision, before checkout" copy="The score is one signal. Your reasons and recommended pause matter more."/><div className="verdict-layout"><section className={`verdict-card ${result.riskLevel.toLowerCase()}`}><div className="verdict-top"><div className="verdict-gauge" style={{'--score':result.impulseScore}}><span><strong>{result.impulseScore}</strong>/100</span></div><div><span className="verdict-label">{pretty(result.riskLevel)} impulse risk</span><h2>{result.recommendation}</h2><p><Clock3/> Recommended pause: <b>{result.waitingPeriod}</b></p></div></div><div className="purchase-recap"><ShoppingBag/><span><b>{result.productName}</b><small>{pretty(result.category)}</small></span><strong>{money(result.price)}</strong></div>{result.similarItemAlert&&<div className="similar-alert"><PackageCheck/>{result.similarItemAlert}</div>}<h3>What influenced this result</h3><div className="reason-grid">{result.reasons.map((r,i)=><div key={r}><span>{i+1}</span>{r}</div>)}</div></section><aside className="next-decision"><div className="advisor-orb"><BrainCircuit/></div><span className="mini-label">CHOOSE YOUR NEXT STEP</span><h2>What will you do now?</h2><p>Recording the outcome improves your insights and keeps savings totals honest.</p><button className="cool-button" disabled={saved} onClick={wishlist}><Clock3/>{saved?'Added to cooling-off list':'Start the cooling-off period'}</button><button className="avoid-button" onClick={()=>decision('AVOIDED')}><ShieldCheck/>I’ll skip this purchase</button><button className="bought-button" onClick={()=>decision('PURCHASED')}><ShoppingBag/>I decided to buy it</button><div className={`recorded ${result.decision.toLowerCase()}`}>Current decision: <b>{pretty(result.decision)}</b></div><button className="evaluate-again" onClick={reset}>Evaluate another product <ArrowRight/></button></aside></div></>;
 return <><PageTitle eyebrow="IMPULSE CHECK" title="Should this go in your cart?" copy="A short guided reflection—designed to slow the moment down without judging your choice."/><div className="evaluate-shell"><aside className="evaluate-steps"><div className="step-brand"><BrainCircuit/><span><b>Decision check</b><small>About 2 minutes</small></span></div>{[['Product','What caught your eye'],['Context','Need, budget & timing'],['Triggers','Emotion & influence']].map(([a,b],i)=><button type="button" className={`${step===i?'current':''} ${step>i?'done':''}`} key={a} onClick={()=>i<step&&setStep(i)}><span>{step>i?<Check/>:i+1}</span><div><b>{a}</b><small>{b}</small></div></button>)}<div className="evaluation-tip"><Lightbulb/><span><b>There are no “good” answers.</b>Honesty gives you a more useful result.</span></div></aside><main className="evaluate-workspace"><div className="mobile-step">Step {step+1} of 3 <i><span style={{width:`${(step+1)*33.33}%`}}/></i></div>{step===0&&<section className="eval-section"><span className="section-icon"><ShoppingBag/></span><h2>Let’s start with the product</h2><p>Capture what you’re considering and where the interest came from.</p><div className="eval-form-grid"><label className="span-two">What do you want to buy?<input autoFocus required placeholder="e.g. Noise-cancelling headphones" value={form.productName} onChange={e=>set('productName',e.target.value)}/></label><label>Category<select value={form.category} onChange={e=>set('category',e.target.value)}>{categories.map(c=><option value={c} key={c}>{pretty(c)}</option>)}</select></label><label>Current price<div className="input-icon"><IndianRupee/><input type="number" min="1" placeholder="0" value={form.price} onChange={e=>set('price',e.target.value)}/></div></label><label>Where did you discover it?<select value={form.sourceOfInterest} onChange={e=>set('sourceOfInterest',e.target.value)}><option value="SOCIAL_MEDIA">Social media</option><option value="ADVERTISEMENT">Online advertisement</option><option value="IN_STORE">In a store</option><option value="FRIEND">Friend or family</option><option value="SEARCH">I searched for it</option><option value="OTHER">Somewhere else</option></select></label><label className="discount-box"><span><BadgePercent/><b>Is it currently discounted?</b></span><input type="checkbox" checked={form.discountAvailable} onChange={e=>set('discountAvailable',e.target.checked)}/></label>{form.discountAvailable&&<label>Discount percentage<input type="number" min="0" max="100" value={form.discountPercentage} onChange={e=>set('discountPercentage',e.target.value)}/><small>You would pay approximately <b>{money(priceAfterDiscount)}</b></small></label>}<label className="span-two">Optional note<textarea placeholder="What makes this product appealing right now?" value={form.description} onChange={e=>set('description',e.target.value)}/></label></div></section>}{step===1&&<section className="eval-section"><span className="section-icon"><Target/></span><h2>Need, planning, and affordability</h2><p>Separate long-term value from the intensity of the current moment.</p><div className="context-cards">{questions.slice(0,4).map(([key,title,hint])=><div className="reflection-card" key={key}><div><h3>{title}</h3><p>{hint}</p></div><Choice value={form[key]} onChange={v=>set(key,v)}/></div>)}</div><label className="consideration">How long have you been considering it?<div>{['Today','A few days','A week','Several weeks','One month or longer'].map(x=><button type="button" className={form.considerationPeriod===x?'active':''} onClick={()=>set('considerationPeriod',x)} key={x}>{x}</button>)}</div></label>{budget?.id?<div className="budget-context"><ShieldCheck/><span><b>{money(budget.remainingBudget)} remaining in your awareness budget</b><small>This purchase is automatically marked {form.withinBudget?'within':'outside'} that amount.</small></span></div>:<div className="budget-context missing"><TriangleAlert/><span><b>No monthly budget set</b><small>You can continue, but setting a budget makes affordability guidance more accurate.</small></span><a href="/budget">Set budget</a></div>}</section>}{step===2&&<section className="eval-section"><span className="section-icon"><Sparkles/></span><h2>Notice the triggers around the urge</h2><p>Advertising, scarcity, and emotion can quietly change how valuable something feels.</p><div className="mood-picker"><h3>How do you feel right now?</h3><div>{moods.map(([value,label])=><button type="button" className={form.emotionalState===value?'active':''} onClick={()=>set('emotionalState',value)} key={value}><span>{value==='HAPPY'?'😊':value==='EXCITED'?'🤩':value==='BORED'?'😐':value==='STRESSED'?'😣':value==='SAD'?'😔':value==='FRUSTRATED'?'😤':'😌'}</span>{label}</button>)}</div></div><div className="context-cards compact">{questions.slice(4).map(([key,title,hint])=><div className="reflection-card" key={key}><div><h3>{title}</h3><p>{hint}</p></div><Choice value={form[key]} onChange={v=>set(key,v)}/></div>)}</div></section>}{error&&<div className="eval-error"><TriangleAlert/>{error}</div>}<footer className="evaluate-footer"><button type="button" className="back-button" disabled={step===0} onClick={()=>setStep(s=>s-1)}><ArrowLeft/>Back</button><span>{step===2?`${answered}/${questions.length} answered`:'Your progress is saved on this screen'}</span>{step<2?<button type="button" className="continue-button" onClick={next}>Continue<ArrowRight/></button>:<button type="button" disabled={busy} className="continue-button analyze" onClick={evaluate}><BrainCircuit/>{busy?'Analyzing…':'Reveal my decision score'}</button>}</footer></main></div></>}
